<script setup lang="ts">
import type { Band } from '../types';
import { newBand } from '../templateRules';
const props=defineProps<{modelValue:Band[];mode:'weight'|'piece';prefix:string;disabled?:boolean}>();
const emit=defineEmits<{'update:modelValue':[bands:Band[]]}>();
function update(index:number,field:keyof Band,event:Event){const value=(event.target as HTMLInputElement).value;emit('update:modelValue',props.modelValue.map((band,i)=>i===index?{...band,[field]:value.trim()===''?(field==='lowerExclusive'?0:null):Number(value)}:{...band}));}
function infinity(index:number,checked:boolean){emit('update:modelValue',props.modelValue.map((band,i)=>i===index?{...band,upperInclusive:checked?null:band.lowerExclusive+1}:{...band}));}
function add(){const last=props.modelValue.at(-1);emit('update:modelValue',[...props.modelValue,{...newBand(),lowerExclusive:last?.upperInclusive??last?.lowerExclusive??0}]);}
const fields=['firstQuantity','firstFee','additionalQuantity','additionalFee'] as const;
</script>
<template><div class="overflow-x-auto"><table class="w-full min-w-[960px] table-fixed text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-600"><tr><th class="w-36">区间下限（不含）</th><th class="w-44">区间上限（含）</th><th>{{ mode==='piece'?'首件（件）':'首重（kg）' }}</th><th>首费（元）</th><th>{{ mode==='piece'?'续件（件）':'续重（kg）' }}</th><th>续费（元）</th><th class="w-16">操作</th></tr></thead><tbody><tr v-for="(band,index) in modelValue" :key="index" class="border-t border-slate-200"><td><input :value="band.lowerExclusive" :disabled="disabled" :aria-label="`区间${index+1}下限`" type="number" min="0" :step="mode==='piece'?1:'any'" class="number" @input="update(index,'lowerExclusive',$event)"></td><td><div class="flex items-center gap-2"><input :value="band.upperInclusive??''" :disabled="disabled || band.upperInclusive===null" :aria-label="`区间${index+1}上限`" type="number" min="0" :step="mode==='piece'?1:'any'" class="number min-w-0" :placeholder="band.upperInclusive===null?'∞':''" @input="update(index,'upperInclusive',$event)"><label class="flex shrink-0 items-center gap-1 text-xs"><input type="checkbox" :disabled="disabled" :checked="band.upperInclusive===null" :aria-label="`区间${index+1}无上限`" @change="infinity(index,($event.target as HTMLInputElement).checked)">∞</label></div></td><td v-for="field in fields" :key="field"><input :data-testid="`${prefix}-${field}-${index}`" :value="band[field]??''" :disabled="disabled" :aria-label="`${field}-${index+1}`" type="number" min="0" :step="mode==='piece' && field.endsWith('Quantity')?1:'any'" class="number" placeholder="未填写" @input="update(index,field,$event)"></td><td><button type="button" :disabled="disabled" class="text-rose-600 disabled:opacity-40" :aria-label="`删除区间${index+1}`" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">删除</button></td></tr></tbody></table><button type="button" :disabled="disabled" class="m-3 rounded border border-dashed border-indigo-300 px-4 py-2 text-xs text-indigo-600 disabled:opacity-40" @click="add">＋ 添加区间</button></div></template>
<style scoped>th,td{@apply px-3 py-3;}.number{@apply w-full rounded border border-slate-200 bg-white px-2 py-2 text-sm outline-none focus:border-indigo-400 disabled:bg-slate-50;}</style>
